#!/usr/bin/env node
/**
 * 工具展示元数据镜像生成脚本（单一来源：backend/tools/** 的 ToolDeclaration）
 *
 * 背景：frontend/src/utils/tools/** 下约 50 个文件镜像后端 backend/tools/** 的
 * 工具展示元数据，工具名/参数/描述靠人工保持一致，易漂移。本脚本把后端工具声明
 * 中「可静态确定」的部分（description 模板 + 参数摘要）提取为前端生成物：
 *
 *   - 单一来源：backend/tools 目录下各工具文件中的 ToolDeclaration 对象字面量
 *   - 生成物：frontend/src/utils/tools/__generated__/toolMeta.ts（AUTO-GENERATED）
 *   - 前端镜像文件的 descriptionFormatter 从生成物取描述（toolMetaLookup.ts），
 *     label/icon 等前端特有展示元数据仍保留手写
 *
 * 提取策略（宁缺毋滥）：
 *   - description：仅当能静态求值为稳定字符串时提取；运行时动态构造
 *     （函数调用、导入常量插值、getter、三元等）一律标记 descriptionDynamic 并省略。
 *   - parameters：提取每个顶层参数的字面量 type/description/enum/default/required；
 *     动态字段省略该字段并置 parametersDynamic。
 *   - 支持的字面量子集：字符串（含转义）、模板字符串（仅可解析的 ${标识符} 插值）、
 *     数字、布尔、null、数组（含 [...模块级常量] 展开）、对象（含简写属性）、
 *     '+' 字符串拼接、以及上述引用的 const/let 初值常量（含 'NAME += 字面量' 追加链、
 *     函数参数默认值）。
 *   - 多根工作区等环境相关分支（if/三元）不解析，取单根默认值（环境无关、幂等）。
 *
 * 用法：
 *   node scripts/generate-tool-meta.mjs            生成（幂等，重复运行结果一致）
 *   node scripts/generate-tool-meta.mjs --check    校验生成物与后端声明一致（防漂移；供 jest 测试调用）
 *   node scripts/generate-tool-meta.mjs --report   输出提取覆盖率报告
 *   node scripts/generate-tool-meta.mjs --help     帮助
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const BACKEND_TOOLS_DIR = path.join(ROOT, 'backend', 'tools');
const OUT_DIR = path.join(ROOT, 'frontend', 'src', 'utils', 'tools', '__generated__');
const OUT_FILE = path.join(OUT_DIR, 'toolMeta.ts');

const GENERATED_HEADER = `/**
 * AUTO-GENERATED by scripts/generate-tool-meta.mjs — 请勿手改！
 *
 * 单一来源：backend/tools 下各工具文件的 ToolDeclaration（工具名 / description / 参数 schema）。
 * 只包含「可静态求值」的确定性字段；运行时动态构造的 description/参数被省略并置
 * descriptionDynamic / parametersDynamic 标记（前端据此回退手写文案）。
 * 重新生成：node scripts/generate-tool-meta.mjs
 */
`;

/* ------------------------------------------------------------------ */
/* 小型 TS 字面量求值器（只支持确定性字面量子集，其余视为 dynamic）    */
/* ------------------------------------------------------------------ */

/**
 * 从 source 中收集可静态求值的常量表（模块级 + 函数体第一层），供标识符解析：
 * - const NAME = <literal> / let NAME = <literal>（取初值）
 * - NAME += <literal>（无条件追加链，字符串拼接 / 数值相加）
 * - 函数参数默认值：function f(param: Type = <literal>)
 * 条件分支内的赋值（if/三元）不收集——环境相关，宁缺毋滥。
 */
function collectConsts(source) {
    const consts = new Map();
    const depthMap = new Map(); // name -> 声明时深度（用于 += 链匹配）
    let depth = 0;

    for (let i = 0; i < source.length; i++) {
        const c = source[i];
        if (c === '/' && source[i + 1] === '/') { while (i < source.length && source[i] !== '\n') i++; continue; }
        if (c === '/' && source[i + 1] === '*') { const end = source.indexOf('*/', i + 2); i = end === -1 ? source.length : end + 1; continue; }
        if (c === "'" || c === '"') { i = skipString(source, i, c); continue; }
        if (c === '`') { i = skipTemplate(source, i); continue; }
        if (c === '{') { depth++; continue; }
        if (c === '}') { depth--; continue; }
        if (depth > 2) continue; // 只收集模块级（0）、工厂函数体第一层（1）与箭头声明体（2）

        if (c === 'f' && source.startsWith('function', i)) {
            // 函数签名里的参数默认值：function name(a: T = 1, b = 'x')
            const sigEnd = source.indexOf(')', i);
            const sig = source.slice(i, sigEnd);
            const paramRe = /([A-Za-z_$][\w$]*)\s*(?::[^=,)]+)?\s*=\s*/g;
            let m;
            while ((m = paramRe.exec(sig)) !== null) {
                const sub = new ValueParser(sig, consts, m.index + m[0].indexOf('=') + 1);
                const val = sub.parseValue();
                if (val.ok && isPlainLiteral(val.value)) {
                    consts.set(m[1], val.value);
                    depthMap.set(m[1], depth);
                }
            }
            i = sigEnd;
            continue;
        }

        const isConst = source.startsWith('const ', i) || source.startsWith('let ', i);
        if (isConst) {
            const m = /^(?:const|let)\s+([A-Za-z_$][\w$]*)\s*=\s*/.exec(source.slice(i));
            if (m) {
                const vp = new ValueParser(source, consts, i + m[0].length);
                const val = vp.parseValue();
                if (val.ok && isPlainLiteral(val.value)) {
                    consts.set(m[1], val.value);
                    depthMap.set(m[1], depth);
                }
                i = vp.i;
                continue;
            }
        }

        const plusAssign = /^([A-Za-z_$][\w$]*)\s*\+=\s*/.exec(source.slice(i));
        if (plusAssign && depthMap.get(plusAssign[1]) === depth && consts.has(plusAssign[1])) {
            const vp = new ValueParser(source, consts, i + plusAssign[0].length);
            const val = vp.parseValue();
            if (val.ok) {
                const cur = consts.get(plusAssign[1]);
                if (typeof cur === 'string' && typeof val.value === 'string') {
                    consts.set(plusAssign[1], cur + val.value);
                } else if (typeof cur === 'number' && typeof val.value === 'number') {
                    consts.set(plusAssign[1], cur + val.value);
                }
            }
            i = vp.i;
            continue;
        }
    }
    return consts;
}

/** 跳过普通字符串，返回结束引号的位置 */
function skipString(source, start, quote) {
    let i = start + 1;
    while (i < source.length) {
        if (source[i] === '\\') { i += 2; continue; }
        if (source[i] === quote) return i;
        i++;
    }
    return i;
}

/** 跳过模板字符串（含 ${...} 内部），返回结束反引号的位置 */
function skipTemplate(source, start) {
    let i = start + 1;
    while (i < source.length) {
        if (source[i] === '\\') { i += 2; continue; }
        if (source[i] === '`') return i;
        if (source[i] === '$' && source[i + 1] === '{') {
            let d = 1;
            i += 2;
            while (i < source.length && d > 0) {
                if (source[i] === "'" || source[i] === '"') { i = skipString(source, i, source[i]) + 1; continue; }
                if (source[i] === '`') { i = skipTemplate(source, i) + 1; continue; }
                if (source[i] === '{') d++;
                else if (source[i] === '}') d--;
                i++;
            }
            continue;
        }
        i++;
    }
    return i;
}

function isPlainLiteral(v) {
    return typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean'
        || v === null
        || (Array.isArray(v) && v.every(isPlainLiteral))
        || (v !== null && typeof v === 'object' && Object.values(v).every(isPlainLiteral));
}

/**
 * 递归下降求值器：从 pos 开始求值一个值表达式。
 * 返回 { ok, value, dynamicKeys, spreadDynamic, i }：
 * - ok: 语法上是否是一个可识别的字面量/标识符/拼接表达式（即使含动态成分）
 * - value: 求值结果（动态成分不写入）
 * - dynamicKeys: 对象内无法求值的键名集合
 * - spreadDynamic: 对象/数组内出现无法求值的展开
 */
class ValueParser {
    constructor(source, consts, pos) {
        this.src = source;
        this.consts = consts;
        this.i = pos;
        this.dynKeysTotal = 0; // 全解析过程中动态键总数（含嵌套对象）
        this.spreadDynamicTotal = 0; // 全解析过程中无法求值的展开总数（含嵌套）
    }

    skipWs() {
        while (this.i < this.src.length) {
            const c = this.src[this.i];
            if (c === ' ' || c === '\t' || c === '\n' || c === '\r') { this.i++; continue; }
            if (c === '/' && this.src[this.i + 1] === '/') { while (this.i < this.src.length && this.src[this.i] !== '\n') this.i++; continue; }
            if (c === '/' && this.src[this.i + 1] === '*') { const end = this.src.indexOf('*/', this.i + 2); this.i = end === -1 ? this.src.length : end + 2; continue; }
            break;
        }
    }

    parseValue() {
        this.skipWs();
        return this.parseAdditive();
    }

    parseAdditive() {
        let left = this.parsePrimary();
        if (!left.ok) return left;
        this.skipWs();
        while (this.src[this.i] === '+') {
            this.i++;
            const right = this.parsePrimary();
            if (!right.ok) return { ok: false, i: this.i };
            if (typeof left.value === 'string' || typeof right.value === 'string') {
                left = { ok: true, value: String(left.value ?? '') + String(right.value ?? ''), i: right.i };
            } else {
                left = { ok: true, value: left.value + right.value, i: right.i };
            }
            this.skipWs();
        }
        // 三元表达式不是确定性字面量：即使条件可解析也不能取左值
        if (this.src[this.i] === '?') return { ok: false, i: this.i, dynamic: true };
        return left;
    }

    /** 跳过无法求值的动态值（函数调用/三元等），停在下一个顶层 ',' 或 stopChar */
    skipDynamicValue(stopChar) {
        let depth = 0;
        while (this.i < this.src.length) {
            const c = this.src[this.i];
            if (c === "'" || c === '"') { this.i = skipString(this.src, this.i, c) + 1; continue; }
            if (c === '`') { this.i = skipTemplate(this.src, this.i) + 1; continue; }
            if (c === '/' && this.src[this.i + 1] === '/') { while (this.i < this.src.length && this.src[this.i] !== '\n') this.i++; continue; }
            if (c === '/' && this.src[this.i + 1] === '*') { const end = this.src.indexOf('*/', this.i + 2); this.i = end === -1 ? this.src.length : end + 2; continue; }
            if (c === '(' || c === '[' || c === '{') depth++;
            else if (c === ',' && depth === 0) return;
            else if (c === stopChar && depth === 0) return;
            else if (c === ')' || c === ']' || c === '}') { if (depth > 0) depth--; }
            this.i++;
        }
    }

    parsePrimary() {
        this.skipWs();
        const c = this.src[this.i];
        if (c === "'" || c === '"') return this.parseString();
        if (c === '`') return this.parseTemplate();
        if (c === '[') return this.parseArray();
        if (c === '{') return this.parseObject();
        if (c === '(') {
            this.i++;
            const v = this.parseValue();
            this.skipWs();
            if (this.src[this.i] === ')') this.i++;
            return v;
        }
        if (/[0-9]/.test(c)) {
            const m = /^[0-9]+(?:\.[0-9]+)?/.exec(this.src.slice(this.i));
            if (m) { this.i += m[0].length; return { ok: true, value: Number(m[0]), i: this.i }; }
            return { ok: false, i: this.i };
        }
        if (c === 't' && this.src.startsWith('true', this.i)) { this.i += 4; return { ok: true, value: true, i: this.i }; }
        if (c === 'f' && this.src.startsWith('false', this.i)) { this.i += 5; return { ok: true, value: false, i: this.i }; }
        if (c === 'n' && this.src.startsWith('null', this.i)) { this.i += 4; return { ok: true, value: null, i: this.i }; }
        if (/[A-Za-z_$]/.test(c)) {
            const m = /^[A-Za-z_$][\w$]*/.exec(this.src.slice(this.i));
            const name = m[0];
            this.i += name.length;
            if (this.consts.has(name)) {
                return { ok: true, value: this.consts.get(name), i: this.i };
            }
            return { ok: false, i: this.i, unresolvableIdent: name };
        }
        return { ok: false, i: this.i };
    }

    parseString() {
        const strStart = this.i; // 入口位置（开引号处）——非法转义分支据此跳过整个字符串
        const quote = this.src[this.i];
        this.i++;
        let out = '';
        while (this.i < this.src.length) {
            const c = this.src[this.i];
            if (c === quote) { this.i++; return { ok: true, value: out, i: this.i }; }
            if (c === '\\') {
                const esc = this.src[this.i + 1];
                if (esc === 'n') out += '\n';
                else if (esc === 't') out += '\t';
                else if (esc === 'r') out += '\r';
                else if (esc === 'b') out += '\b';
                else if (esc === 'f') out += '\f';
                else if (esc === 'v') out += '\v';
                else if (esc === 'u' && /^[0-9a-fA-F]{4}/.test(this.src.slice(this.i + 2, this.i + 6))) {
                    out += String.fromCharCode(parseInt(this.src.slice(this.i + 2, this.i + 6), 16));
                    this.i += 4;
                } else if (esc === 'x' && /^[0-9a-fA-F]{2}/.test(this.src.slice(this.i + 2, this.i + 4))) {
                    // \xNN 转义（\x00-\xFF），与 JS 字符串语义一致；共消费 4 字符（\ x N N）
                    out += String.fromCharCode(parseInt(this.src.slice(this.i + 2, this.i + 4), 16));
                    this.i += 2;
                } else if (esc === 'x' || esc === 'u') {
                    // 非法 \x/\u 转义（hex 位数不足，如 '\x4'、'\u123'；含不支持的 \u{...} 码点形式）：
                    // JS 中属语法错误或本求值器不支持，无法静态求值——显式标记 dynamic（宁缺毋滥），
                    // 不再落入下方字面 fallback 输出 'x4'/'u123' 之类错误文本。
                    // 恢复点须位于整个字符串结尾之后（与模板分支 skipTemplate 语义对齐）：
                    // 若停留在字符串中间，调用方 skipDynamicValue 会把串内字符当顶层结构扫描，
                    // 可能越过本字符串结尾误跳下一个字符串字面量。
                    this.i = Math.min(skipString(this.src, strStart, quote) + 1, this.src.length);
                    return { ok: false, i: this.i, dynamic: true };
                } else if (esc === '0' || (esc >= '1' && esc <= '7')) {
                    // \0 与遗留八进制转义（\1-\7、\01、\012…）：JS 中 \0 后随非数字为 NUL、
                    // 其余为遗留八进制（严格模式/ESM 属语法错误），求值器不静态解码——与 \x/\u
                    // 一致显式标记 dynamic（选 dynamic 方案），不再落入字面 fallback 输出 '0'/'1'
                    // 之类错误文本；同样跳过整个字符串，恢复点在串尾之后。
                    // 边界说明：\8/\9 在严格模式（本文件为 .mjs/ESM）下同为语法错误，此处未单独列出——
                    // 合法源码不可达，落入下方字面 fallback（out += esc）无实际影响。
                    this.i = Math.min(skipString(this.src, strStart, quote) + 1, this.src.length);
                    return { ok: false, i: this.i, dynamic: true };
                } else if (esc !== undefined) out += esc;
                this.i += 2;
                continue;
            }
            out += c;
            this.i++;
        }
        return { ok: false, i: this.i };
    }

    parseTemplate() {
        const tplStart = this.i; // 开头的 `
        this.i++;
        let out = '';
        while (this.i < this.src.length) {
            const c = this.src[this.i];
            if (c === '`') { this.i++; return { ok: true, value: out, i: this.i }; }
            if (c === '\\') {
                const esc = this.src[this.i + 1];
                out += esc === 'n' ? '\n' : esc === 't' ? '\t' : esc === 'r' ? '\r' : esc;
                this.i += 2;
                continue;
            }
            if (c === '$' && this.src[this.i + 1] === '{') {
                this.i += 2;
                // 只支持 ${标识符} 的简单插值；其余视为 dynamic
                const m = /^[A-Za-z_$][\w$]*\s*\}/.exec(this.src.slice(this.i));
                if (m) {
                    const name = m[0].replace(/\s*\}$/, '');
                    if (this.consts.has(name)) {
                        out += String(this.consts.get(name));
                        this.i += m[0].length;
                        continue;
                    }
                }
                // 不可解析的插值：跳到整个模板结尾再标记 dynamic，避免调用方在模板中间误停
                this.i = skipTemplate(this.src, tplStart) + 1;
                return { ok: false, i: this.i, dynamic: true };
            }
            out += c;
            this.i++;
        }
        return { ok: false, i: this.i };
    }

    parseArray() {
        this.i++; // [
        const items = [];
        let spreadDynamic = false;
        this.skipWs();
        if (this.src[this.i] === ']') { this.i++; return { ok: true, value: items, i: this.i, spreadDynamic }; }
        while (this.i < this.src.length) {
            this.skipWs();
            if (this.src[this.i] === ']') { this.i++; break; } // 尾随逗号
            if (this.src.startsWith('...', this.i)) {
                this.i += 3;
                // 纯标识符展开（如 [...RANGES]）可内联；复合表达式一律跳过并标记 dynamic
                const idMatch = /^([A-Za-z_$][\w$]*)(?=\s*[,}\]]|$)/.exec(this.src.slice(this.i));
                let inlined = false;
                if (idMatch && this.consts.has(idMatch[1])) {
                    const val = this.consts.get(idMatch[1]);
                    if (Array.isArray(val)) { items.push(...val); inlined = true; }
                    // 对象不可迭代：JS 中 [...obj] 运行时抛 TypeError，无法静态内联 → 走下方 dynamic 分支
                }
                if (!inlined) {
                    spreadDynamic = true; // 无法求值的展开：数组内容不确定
                    this.spreadDynamicTotal++;
                }
                this.skipDynamicValue(']');
                this.skipWs();
                if (this.src[this.i] === ',') { this.i++; continue; }
                if (this.src[this.i] === ']') { this.i++; break; }
                return { ok: false, i: this.i };
            }
            const v = this.parseValue();
            if (!v.ok) {
                spreadDynamic = true; // 元素动态：数组不完整
                this.spreadDynamicTotal++;
                this.skipDynamicValue(']');
                this.skipWs();
                if (this.src[this.i] === ',') { this.i++; continue; }
                if (this.src[this.i] === ']') { this.i++; break; }
                return { ok: false, i: this.i };
            }
            items.push(v.value);
            this.skipWs();
            if (this.src[this.i] === ',') { this.i++; continue; }
            if (this.src[this.i] === ']') { this.i++; break; }
            return { ok: false, i: this.i };
        }
        return { ok: true, value: items, i: this.i, spreadDynamic };
    }

    parseObject() {
        this.i++; // {
        const out = {};
        const dynamicKeys = new Set();
        let spreadDynamic = false;
        this.skipWs();
        if (this.src[this.i] === '}') { this.i++; return { ok: true, value: out, i: this.i, dynamicKeys, spreadDynamic }; }
        while (this.i < this.src.length) {
            this.skipWs();
            if (this.src[this.i] === '}') { this.i++; break; } // 尾随逗号
            if (this.src.startsWith('...', this.i)) {
                this.i += 3;
                // 纯标识符展开（如 ...singleModeProperties）可内联；复合表达式一律跳过并标记 dynamic
                const idMatch = /^([A-Za-z_$][\w$]*)(?=\s*[,}\]]|$)/.exec(this.src.slice(this.i));
                let inlined = false;
                if (idMatch && this.consts.has(idMatch[1])) {
                    const val = this.consts.get(idMatch[1]);
                    if (val !== null && typeof val === 'object' && !Array.isArray(val)) {
                        Object.assign(out, val);
                        inlined = true;
                    }
                }
                if (!inlined) {
                    spreadDynamic = true; // 无法求值的展开：对象内容不确定
                    this.spreadDynamicTotal++;
                }
                this.skipDynamicValue('}');
                this.skipWs();
                if (this.src[this.i] === ',') { this.i++; continue; }
                if (this.src[this.i] === '}') { this.i++; break; }
                return { ok: false, i: this.i };
            }
            let key;
            const c = this.src[this.i];
            if (c === "'" || c === '"') {
                const ks = this.parseString();
                if (!ks.ok) return { ok: false, i: this.i };
                key = ks.value;
                this.skipWs();
                if (this.src[this.i] !== ':') return { ok: false, i: this.i };
                this.i++;
            } else if (/[A-Za-z_$]/.test(c)) {
                const m = /^[A-Za-z_$][\w$]*/.exec(this.src.slice(this.i));
                key = m[0];
                this.i += key.length;
                this.skipWs();
                if (this.src[this.i] !== ':') {
                    // 简写属性：key 单独出现，值取常量表（取不到则 dynamic）
                    if (this.consts.has(key)) {
                        out[key] = this.consts.get(key);
                    } else {
                        dynamicKeys.add(key);
                        this.dynKeysTotal++;
                    }
                    this.skipWs();
                    if (this.src[this.i] === ',') { this.i++; continue; }
                    if (this.src[this.i] === '}') { this.i++; break; }
                    return { ok: false, i: this.i };
                }
                this.i++; // :
            } else {
                return { ok: false, i: this.i };
            }
            const v = this.parseValue();
            if (v.ok) {
                out[key] = v.value;
            } else {
                dynamicKeys.add(key);
                this.dynKeysTotal++;
                this.skipDynamicValue('}'); // 动态值：跳到下一个顶层 , 或 }
            }
            this.skipWs();
            if (this.src[this.i] === ',') { this.i++; continue; }
            if (this.src[this.i] === '}') { this.i++; break; }
            return { ok: false, i: this.i };
        }
        return { ok: true, value: out, i: this.i, dynamicKeys, spreadDynamic };
    }
}

/* ------------------------------------------------------------------ */
/* 声明发现：在 backend/tools 各工具文件中定位 ToolDeclaration 对象字面量 */
/* ------------------------------------------------------------------ */

/** 收集文件内容中所有不在字符串/注释/模板内的 '{' 位置 */
function collectBracePositions(source) {
    const positions = [];
    for (let i = 0; i < source.length; i++) {
        const c = source[i];
        if (c === '/' && source[i + 1] === '/') { while (i < source.length && source[i] !== '\n') i++; continue; }
        if (c === '/' && source[i + 1] === '*') { const end = source.indexOf('*/', i + 2); i = end === -1 ? source.length : end + 1; continue; }
        if (c === "'" || c === '"') { i = skipString(source, i, c); continue; }
        if (c === '`') { i = skipTemplate(source, i); continue; }
        if (c === '{') positions.push(i);
    }
    return positions;
}

/**
 * 从单个 backend/tools 文件中提取工具声明候选。
 * 发现方式：找到所有 `name: '<tool>'` 字面量，向前扫描最近的、能解析为
 * 含 name + parameters 键的对象字面量（即 ToolDeclaration 形态）。
 */
function findDeclarationCandidates(relPath, source) {
    const consts = collectConsts(source);
    const braces = collectBracePositions(source);
    const candidates = [];
    const nameRe = /\bname\s*:\s*'([a-z][a-z0-9_]*)'/g;
    let m;
    while ((m = nameRe.exec(source)) !== null) {
        const toolName = m[1];
        const namePos = m.index;
        // 从最近到最远尝试所有 '{' 位置
        for (let b = braces.length - 1; b >= 0; b--) {
            if (braces[b] > namePos) continue;
            const vp = new ValueParser(source, consts, braces[b]);
            const obj = vp.parseObject();
            if (!obj.ok) continue;
            const value = obj.value;
            if (typeof value.name === 'string' && value.name === toolName
                && value.parameters && typeof value.parameters === 'object'
                && !Array.isArray(value.parameters)) {
                candidates.push({
                    toolName,
                    source: relPath,
                    start: braces[b],
                    end: obj.i,
                    dynamicKeys: obj.dynamicKeys,
                    spreadDynamic: obj.spreadDynamic,
                    dynKeysTotal: vp.dynKeysTotal,
                    spreadDynamicTotal: vp.spreadDynamicTotal,
                    raw: value,
                });
                break; // 找到最近的外层声明即止
            }
        }
    }
    return candidates;
}

/* ------------------------------------------------------------------ */
/* 声明 → 生成物条目                                                   */
/* ------------------------------------------------------------------ */

function extractParameterSummary(propValue) {
    const summary = {};
    if (typeof propValue.type === 'string') summary.type = propValue.type;
    if (typeof propValue.description === 'string') summary.description = propValue.description;
    if (Array.isArray(propValue.enum) && propValue.enum.every(e => typeof e === 'string')) {
        summary.enum = propValue.enum;
    }
    if (propValue.default !== undefined
        && (typeof propValue.default === 'string' || typeof propValue.default === 'number' || typeof propValue.default === 'boolean')) {
        summary.default = propValue.default;
    }
    if (propValue.items && typeof propValue.items === 'object' && !Array.isArray(propValue.items)) {
        const items = {};
        if (typeof propValue.items.type === 'string') items.type = propValue.items.type;
        if (typeof propValue.items.description === 'string') items.description = propValue.items.description;
        if (Array.isArray(propValue.items.enum) && propValue.items.enum.every(e => typeof e === 'string')) {
            items.enum = propValue.items.enum;
        }
        if (Object.keys(items).length > 0) summary.items = items;
    }
    const dynamic = typeof summary.type !== 'string';
    return { summary, dynamic };
}

function buildToolEntry(candidate) {
    const { raw, dynamicKeys, spreadDynamic, dynKeysTotal, spreadDynamicTotal, source } = candidate;
    const entry = { parameters: {}, source };

    if (typeof raw.description === 'string' && raw.description.length > 0) {
        entry.description = raw.description;
    } else if (dynamicKeys.has('description') || raw.description === '') {
        // 空描述/动态构造（如 history_search 的 getter 覆盖）→ 运行时不可静态确定
        entry.descriptionDynamic = true;
    }

    const requiredSet = Array.isArray(raw.parameters.required)
        ? new Set(raw.parameters.required.filter(r => typeof r === 'string'))
        : new Set();

    const properties = raw.parameters.properties;
    // 顶层动态键中属于 parameters 部分之外的数量（description/name/category 等不计入）
    const topDynKeysCount = dynamicKeys.size;
    // parameters 结构不完整的情形：parameters 键本身动态、任何嵌套动态键/展开、
    // 或 properties 缺失（嵌套动态键含属性对象内 description/enum 等无法静态提取的字段）
    let parametersDynamic = spreadDynamic
        || dynamicKeys.has('parameters')
        || dynKeysTotal > topDynKeysCount
        || spreadDynamicTotal > 0;
    if (properties && typeof properties === 'object' && !Array.isArray(properties)) {
        for (const [paramName, propValue] of Object.entries(properties)) {
            if (propValue === undefined || propValue === null || typeof propValue !== 'object') {
                parametersDynamic = true;
                continue;
            }
            const { summary, dynamic } = extractParameterSummary(propValue);
            if (dynamic) {
                parametersDynamic = true;
                continue;
            }
            if (requiredSet.has(paramName)) summary.required = true;
            entry.parameters[paramName] = summary;
        }
    } else {
        parametersDynamic = true;
    }
    if (parametersDynamic) entry.parametersDynamic = true;
    if (Object.keys(entry.parameters).length === 0 && !entry.parametersDynamic) {
        entry.parametersDynamic = true;
    }
    return entry;
}

/** 覆盖率评分：描述静态优先，参数越多越好；同分取先出现者（确定性） */
function candidateScore(entry) {
    let score = 0;
    if (entry.description && !entry.descriptionDynamic) score += 1000;
    score += Object.keys(entry.parameters).length;
    if (entry.parametersDynamic) score -= 1;
    return score;
}

function extractAllTools() {
    const byName = new Map();
    const files = walkTsFiles(BACKEND_TOOLS_DIR);
    for (const file of files) {
        const rel = path.relative(ROOT, file).replace(/\\/g, '/');
        // 规范化真实换行（CRLF/CR → LF）：字符串/模板字面量中的真实换行符会被
        // JSON.stringify 编码进生成物，若不统一，Windows 工作区（autocrlf 转 CRLF）
        // 生成的 toolMeta.ts 与 CI（LF 源）不一致，导致 toolMetaParity 测试漂移失败。
        // 源码中显式的 \r\n 转义序列是反斜杠字符，不在此替换范围，语义保持不变。
        const source = fs.readFileSync(file, 'utf8').replace(/\r\n?/g, '\n');
        const candidates = findDeclarationCandidates(rel, source);
        for (const candidate of candidates) {
            const entry = buildToolEntry(candidate);
            const prev = byName.get(candidate.toolName);
            if (!prev || candidateScore(entry) > candidateScore(prev.entry)) {
                byName.set(candidate.toolName, { entry, candidate });
            }
        }
    }
    // 按工具名排序，保证生成物稳定
    return [...byName.entries()].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
}

function walkTsFiles(dir) {
    const out = [];
    for (const name of fs.readdirSync(dir)) {
        const full = path.join(dir, name);
        const stat = fs.statSync(full);
        if (stat.isDirectory()) {
            out.push(...walkTsFiles(full));
        } else if (name.endsWith('.ts')) {
            out.push(full);
        }
    }
    return out;
}

/* ------------------------------------------------------------------ */
/* 生成 TS 文件                                                        */
/* ------------------------------------------------------------------ */

const INTERFACES = `export interface ToolMetaParameterItem {
  type: string
  description?: string
  enum?: string[]
}

export interface ToolMetaParameter {
  type: string
  description?: string
  enum?: string[]
  default?: string | number | boolean
  required?: boolean
  items?: ToolMetaParameterItem
}

export interface ToolMeta {
  /** 工具声明描述（仅静态可提取；运行时动态构造时省略并置 descriptionDynamic） */
  description?: string
  descriptionDynamic?: boolean
  /** 顶层参数摘要：参数名 → { type, description?, enum?, default?, required?, items? } */
  parameters: Record<string, ToolMetaParameter>
  /** parameters 存在无法静态提取的部分时为 true */
  parametersDynamic?: boolean
  /** 声明来源（backend/tools 相对路径），便于核对 */
  source: string
}
`;

function serializeEntry([toolName, { entry }]) {
    const lines = [];
    lines.push(`  '${toolName}': {`);
    if (entry.description !== undefined) {
        lines.push(`    description: ${JSON.stringify(entry.description)},`);
    }
    if (entry.descriptionDynamic) {
        lines.push(`    descriptionDynamic: true,`);
    }
    lines.push(`    parameters: {`);
    for (const [paramName, param] of Object.entries(entry.parameters)) {
        lines.push(`      ${JSON.stringify(paramName)}: ${JSON.stringify(param)},`);
    }
    lines.push(`    },`);
    if (entry.parametersDynamic) {
        lines.push(`    parametersDynamic: true,`);
    }
    lines.push(`    source: ${JSON.stringify(entry.source)},`);
    lines.push(`  },`);
    return lines.join('\n');
}

function buildGeneratedContent(tools) {
    const body = tools.map(serializeEntry).join('\n');
    return `${GENERATED_HEADER}${INTERFACES}\nexport const toolMeta: Record<string, ToolMeta> = {\n${body}\n};\n`;
}

/* ------------------------------------------------------------------ */
/* 报告                                                               */
/* ------------------------------------------------------------------ */

function buildReport(tools) {
    const rows = tools.map(([name, { entry }]) => {
        const desc = entry.description !== undefined
            ? `static(${entry.description.length})`
            : entry.descriptionDynamic ? 'DYNAMIC' : 'missing';
        const params = Object.keys(entry.parameters).length;
        const paramsMark = entry.parametersDynamic ? `${params}+dyn` : String(params);
        return `${name.padEnd(28)} ${desc.padEnd(18)} params=${paramsMark.padEnd(8)} ${entry.source}`;
    });
    const staticDesc = tools.filter(([, { entry }]) => entry.description !== undefined).length;
    const fullParams = tools.filter(([, { entry }]) => !entry.parametersDynamic).length;
    return [
        `工具声明提取报告（共 ${tools.length} 个工具）`,
        `- description 静态可提取：${staticDesc} 个`,
        `- parameters 完整静态提取：${fullParams} 个`,
        `- 其余为运行时动态构造（descriptionDynamic/parametersDynamic 标记，前端回退手写文案）`,
        '',
        ...rows,
        '',
    ].join('\n');
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */

function printHelp() {
    console.log(`用法：
  node scripts/generate-tool-meta.mjs            生成 frontend/src/utils/tools/__generated__/toolMeta.ts（幂等）
  node scripts/generate-tool-meta.mjs --check    校验生成物与 backend/tools 声明一致（防漂移；供 jest 测试调用，不一致时退出码非 0）
  node scripts/generate-tool-meta.mjs --report   输出工具声明提取覆盖率报告
  node scripts/generate-tool-meta.mjs --help     帮助`);
}

function main() {
    const args = process.argv.slice(2);
    if (args.includes('--help') || args.includes('-h')) {
        printHelp();
        return;
    }

    const tools = extractAllTools();
    const content = buildGeneratedContent(tools);

    if (args.includes('--report')) {
        console.log(buildReport(tools));
        return;
    }

    if (args.includes('--check')) {
        let existing = '';
        try {
            // Git 的 core.autocrlf 可能在 Windows checkout 时把生成物的物理行尾转为
            // CRLF；文件行尾本身无语义，不应令 parity 校验误报。字符串中的 `\\r\\n`
            // 转义是普通反斜杠字符，不受此替换影响，仍可检测出元数据语义漂移。
            existing = fs.readFileSync(OUT_FILE, 'utf8').replace(/\r\n?/g, '\n');
        } catch {
            existing = '';
        }
        if (existing === content) {
            console.log(`[tool-meta] OK：${OUT_FILE} 与 backend/tools 声明一致（${tools.length} 个工具）。`);
            return;
        }
        console.error(`[tool-meta] FAIL：${OUT_FILE} 与 backend/tools 声明不一致！`);
        console.error(`[tool-meta] 请运行 node scripts/generate-tool-meta.mjs 重新生成后提交。`);
        const existingLines = existing.split('\n');
        const contentLines = content.split('\n');
        let diffCount = 0;
        const max = Math.max(existingLines.length, contentLines.length);
        for (let i = 0; i < max && diffCount < 12; i++) {
            if (existingLines[i] !== contentLines[i]) {
                console.error(`  - 第 ${i + 1} 行：现有 ${JSON.stringify(existingLines[i] ?? '')}`);
                console.error(`            期望 ${JSON.stringify(contentLines[i] ?? '')}`);
                diffCount++;
            }
        }
        process.exitCode = 1;
        return;
    }

    fs.mkdirSync(OUT_DIR, { recursive: true });
    fs.writeFileSync(OUT_FILE, content, 'utf8');
    console.log(`[tool-meta] 已生成 ${OUT_FILE}（${tools.length} 个工具）。`);
    const staticDesc = tools.filter(([, { entry }]) => entry.description !== undefined).length;
    const fullParams = tools.filter(([, { entry }]) => !entry.parametersDynamic).length;
    console.log(`[tool-meta] description 静态提取 ${staticDesc}/${tools.length}；parameters 完整提取 ${fullParams}/${tools.length}。`);
}

const isDirectRun = process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url;
if (isDirectRun) {
    main();
}

// 导出供调试/测试复用
export {
    collectConsts,
    ValueParser,
    findDeclarationCandidates,
    buildToolEntry,
    extractAllTools,
    buildGeneratedContent,
    buildReport,
};
